-- DROP FUNCTION matricula.verifica_vaga_by_matricula_estudante_serie();

CREATE OR REPLACE FUNCTION matricula.verifica_vaga_by_matricula_estudante_serie()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ declare is_nee boolean; id_vaga_serie int4; is_efetivacao boolean; begin is_efetivacao = false; if exists ( select 1 from matricula.estudante_inscrito ei join matricula.calendario_matricula cm on ei.id_calendario_matricula = cm.id_calendario_matricula where ei.id_estudante = NEW.id_estudante and ei.id_status = 9 and cm.ano = NEW.ano_calendario ) and TG_OP = 'INSERT' then is_efetivacao = true; end if; if exists ( select 1 from matricula.solicitacao_transferencia st join basico.matricula_estudante_serie mes on mes.id_matricula_discente_serie = st.id_matricula_discente_serie where mes.id_estudante = NEW.id_estudante and st.id_status in (2, 4, 8) and st.ano_escolar = NEW.ano_calendario and mes.periodo = NEW.periodo and st.id_matricula_discente_serie_gerado is null ) and TG_OP = 'INSERT' then is_efetivacao = true; end if; if (NEW.id_situacao_matricula_serie not in (5, 9, 6, 4) and ( TG_OP = 'INSERT' or ( TG_OP = 'UPDATE' and ( OLD.id_situacao_matricula_serie in (5, 9, 6, 4) or OLD.id_vaga_serie <> NEW.id_vaga_serie or NEW.id_serie_escola <> OLD.id_serie_escola or NEW.id_turno <> OLD.id_turno or NEW.periodo <> OLD.periodo ) ) ) ) then is_nee = false; if (select count(pne.id_pessoa_necessidade_especial) from public.discente d join comum.pessoa_necessidade_especial pne on pne.id_pessoa = d.id_pessoa where d.id_discente = new.id_estudante ) > 0 then is_nee = true; end if; id_vaga_serie = ( select max(vs.id_vaga_serie) from escola.escola_etapa_ensino_serie eees join matricula.vaga_serie vs on eees.id_escola = vs.id_escola and eees.id_serie = vs.id_serie where eees.id_escola_etapa_ensino_serie = NEW.id_serie_escola and vs.ano_letivo = NEW.ano_calendario and vs.id_turno = NEW.id_turno and vs.periodo = NEW.periodo and not vs.removida ); if id_vaga_serie is null then raise exception 'Trigger: matricula.verifica_vaga_by_matricula_estudante_serie(): Não há vaga_série ATIVA para esta escola/série/período/turno.'; end if; if ( select matricula.verifica_vagas(id_vaga_serie, is_nee)) = false and is_efetivacao = false then raise exception 'Trigger: matricula.verifica_vaga_by_matricula_estudante_serie(): Não há mais vagas para a opção selecionada. '; end if; end if; return new; end; $function$
;



-- DROP FUNCTION matricula.verifica_vagas(int4, bool);

CREATE OR REPLACE FUNCTION matricula.verifica_vagas(id_vaga_serie integer, nee boolean)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$ BEGIN RETURN matricula.verificar_vaga_livre(id_vaga_serie, 0); END; $function$
;


-- DROP FUNCTION matricula.verificar_vaga_livre(int4, int4);

CREATE OR REPLACE FUNCTION matricula.verificar_vaga_livre(id_vaga_serie integer, qtd_vagas_desconsiderar integer)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$ BEGIN RETURN ( SELECT vs.vagas_validadas > ( SELECT COALESCE( sum(( SELECT COALESCE(max(tne.quantidade_vaga), 1) FROM comum.pessoa_necessidade_especial pne JOIN comum.tipo_necessidade_especial tne ON tne.id_tipo_necessidade_especial = pne.id_necessidade_especial WHERE pne.id_pessoa = d.id_pessoa )), 0 ) FROM matricula.renovacao_matricula r JOIN public.discente d ON d.id_discente = r.id_discente WHERE r.id_vaga_serie = vs.id_vaga_serie AND r.data_cancelamento IS NULL AND r.id_nova_serie IS NULL ) + ( SELECT COALESCE( sum(( SELECT COALESCE(max(tne.quantidade_vaga), 1) FROM comum.pessoa_necessidade_especial pne JOIN comum.tipo_necessidade_especial tne ON tne.id_tipo_necessidade_especial = pne.id_necessidade_especial WHERE pne.id_pessoa = d.id_pessoa )), 0 ) FROM matricula.solicitacao_transferencia st INNER JOIN matricula.solicitacao_transferencia_opcao_escola topcao ON topcao.id_solicitacao = st.id_solicitacao_transferencia JOIN basico.matricula_estudante_serie mes ON mes.id_matricula_discente_serie = st.id_matricula_discente_serie JOIN public.discente d ON d.id_discente = mes.id_estudante WHERE st.id_status IN ( 2, 4, 8 ) AND topcao.ordem = 1 AND st.id_calendario_matricula = vs.id_calendario_matricula AND topcao.id_escola = vs.id_escola AND topcao.id_serie = vs.id_serie AND topcao.id_turno = vs.id_turno AND st.id_matricula_discente_serie_gerado IS NULL ) + ( SELECT COALESCE( sum(( SELECT COALESCE(max(tne.quantidade_vaga), 1) FROM matricula.estudante_inscrito_necessidade_especial eine JOIN comum.tipo_necessidade_especial tne ON tne.id_tipo_necessidade_especial = eine.id_tipo_necessidade WHERE eine.id_estudante_inscrito = ei.id_estudante_inscrito )), 0 ) FROM matricula.estudante_inscrito ei INNER JOIN matricula.estudante_inscrito_opcao_escola iopcao ON iopcao.id_estudante_inscrito = ei.id_estudante_inscrito INNER JOIN matricula.estudante_inscrito_processamento eip ON eip.id_estudante_inscrito = ei.id_estudante_inscrito AND eip.id_opcao_escola = iopcao.id_estudante_inscrito_opcao_escola WHERE iopcao.id_vaga_serie = vs.id_vaga_serie AND iopcao.ordem = 1 AND ( ei.id_estudante = 0 OR ei.id_estudante IS NULL ) AND ei.id_status IN ( 1, 4, 6, 7 ) AND eip.id_status IN ( 1, 4, 6, 7 ) ) + ( SELECT COALESCE( sum(( SELECT COALESCE(max(tne.quantidade_vaga), 1) FROM comum.pessoa_necessidade_especial pne JOIN comum.tipo_necessidade_especial tne ON tne.id_tipo_necessidade_especial = pne.id_necessidade_especial WHERE pne.id_pessoa = d.id_pessoa)), 0 ) FROM basico.matricula_estudante_serie mes INNER JOIN escola.escola_etapa_ensino_serie eees ON eees.id_escola_etapa_ensino_serie = mes.id_serie_escola JOIN public.discente d ON d.id_discente = mes.id_estudante WHERE mes.id_situacao_matricula_serie NOT IN ( 4, 5, 6, 9, 10, 11, 12 ) AND mes.id_turno = vs.id_turno AND eees.id_escola = vs.id_escola AND eees.id_serie = vs.id_serie AND mes.ano_calendario = cm.ano AND mes.periodo = vs.periodo ) - $2 FROM matricula.vaga_serie vs INNER JOIN matricula.calendario_matricula cm ON cm.id_calendario_matricula = vs.id_calendario_matricula WHERE vs.id_vaga_serie = $1 ); END; $function$
;


